package com.gymlog.app.data.model

// Class representing an app user
// The uid is the unique identifier generated by Firebase
// usernameLower is the lowercase version of username
// to perform case-insensitive searches in Firestore

data class User(
    val uid: String = "",
    val email: String = "",
    val username: String = "",
    val usernameLower: String = "",
    val photoUrl: String = "https://static.vecteezy.com/system/resources/thumbnails/017/800/528/small/user-simple-flat-icon-illustration-vector.jpg",
    val weightUnit: String = "kg",
    val createdAt: Long = 0L,
    val followersCount: Int = 0,
    val followingCount: Int = 0,
    val followingIds: List<String> = emptyList()

)